SELECT prefecture_name, municipality_name, flood_risk_area_pct, avg_land_price_commercial,
       avg_land_price_residential, land_price_yoy_change
FROM m_re_area
WHERE flood_risk_area_pct >= {{min_flood}}
  AND avg_land_price_commercial >= {{min_price}}
ORDER BY avg_land_price_commercial DESC
LIMIT {{top_n}}

SELECT name, sec_code4, SUM(facility_count) AS facilities, COUNT(*) AS municipalities,
       SUM(book_value_land_m_yen) AS book_value_land_m_yen
FROM m_re_holdings
WHERE fiscal_year = {{fiscal_year}}
  AND population_change_pct <= {{max_change}}
  AND name IS NOT NULL
GROUP BY name, sec_code4
ORDER BY facilities DESC
LIMIT {{top_n}}

SELECT name, sec_code4, COUNT(*) AS municipalities, SUM(facility_count) AS facilities,
       SUM(book_value_land_m_yen) AS book_value_land_m_yen
FROM m_re_holdings
WHERE fiscal_year = {{fiscal_year}}
  AND flood_risk_area_pct >= {{min_flood}}
  AND name IS NOT NULL
GROUP BY name, sec_code4
ORDER BY book_value_land_m_yen DESC
LIMIT {{top_n}}
